import json
from pathlib import Path
names=("lowcost-europa-backup.service","lowcost-europa-offsite-backup.service","lowcost-europa-offsite-backup-health.service")
old="/usr/local/sbin/lowcost-europa-"
new="/srv/projects/lowcost-europa/bin/lowcost-europa-"
out={}
for n in names:
 p=Path("/etc/systemd/system")/n
 try:
  b=p.read_bytes()
  out[n]={"exists":True,"old_prefix":b.count(old.encode()),"new_prefix":b.count(new.encode()),"size":len(b),"uid":p.stat().st_uid,"symlink":p.is_symlink()}
 except OSError:out[n]={"exists":False}
print(json.dumps(out,sort_keys=True))
